css:
.cd-sim{--cd-ink:#1d2b22;--cd-soft:#4a5a50;--cd-bg:#eef5e6;--cd-line:#d5e3c8;--cd-kiwi:#2f7d32;--cd-kiwi2:#256628;--cd-me:#dcf3d0;--cd-red:#b3261e;
 --cd-cash:#b06d00;--cd-team:#6b3fa0;--cd-cust:#c2185b;--cd-fut:#00796b;
 font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:var(--cd-ink);background:var(--cd-bg);
 background-image:radial-gradient(circle at 14px 14px,rgba(47,125,50,.07) 2px,transparent 3px);background-size:30px 30px;
 border-radius:18px;padding:18px;max-width:1180px;margin:0 auto;box-sizing:border-box;}
.cd-sim *{box-sizing:border-box;}
.cd-sim .cd-header{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:8px;}
.cd-sim .cd-title{display:flex;align-items:center;gap:12px;}
.cd-sim .cd-logo{font-size:36px;line-height:1;background:#fff;border:2px solid var(--cd-line);border-radius:50%;padding:8px;transform:rotate(-10deg);}
.cd-sim .cd-title h1{font-size:1.55rem;margin:0;font-weight:800;color:var(--cd-ink);}
.cd-sim .cd-title p{margin:2px 0 0;font-size:.92rem;color:var(--cd-soft);}
.cd-sim .cd-stats{display:flex;gap:8px;flex-wrap:wrap;}
.cd-sim .cd-chip{background:#fff;border:1px solid var(--cd-line);border-radius:999px;padding:6px 12px;font-size:.88rem;color:var(--cd-ink);white-space:nowrap;}
.cd-sim .cd-chip b{font-size:1.02rem;}
.cd-sim .cd-hourchip{background:var(--cd-kiwi2);border-color:var(--cd-kiwi2);color:#fff;}
.cd-sim .cd-starchip b{color:#8a5a00;letter-spacing:1px;}
.cd-sim .cd-intro{margin:0 0 12px;font-size:.95rem;color:var(--cd-soft);max-width:780px;}
.cd-sim.cd-done .cd-intro{display:none;}
.cd-sim .cd-grid{display:grid;grid-template-columns:330px minmax(0,1fr);grid-template-areas:'meters phone' 'extra phone';gap:14px;align-items:start;}
.cd-sim .cd-meters{grid-area:meters;}
.cd-sim .cd-phone{grid-area:phone;max-width:560px;width:100%;justify-self:center;}
.cd-sim .cd-extra{grid-area:extra;display:flex;flex-direction:column;gap:14px;min-width:0;}
.cd-sim .cd-card{background:#fff;border:1px solid var(--cd-line);border-radius:16px;padding:14px 16px;box-shadow:0 2px 0 rgba(40,90,40,.08);}
.cd-sim .cd-card h3{font-size:1.02rem;margin:0 0 8px;font-weight:800;color:var(--cd-ink);}
/* meters */
.cd-sim .cd-meter{margin:10px 0 12px;}
.cd-sim .cd-mhead{display:flex;align-items:center;gap:6px;font-size:.92rem;font-weight:700;}
.cd-sim .cd-memo{font-size:1.15rem;}
.cd-sim .cd-mname{flex:1;}
.cd-sim .cd-mval{font-size:1.15rem;min-width:2.2em;text-align:right;}
.cd-sim .cd-arrow{font-size:.8rem;font-weight:800;letter-spacing:-1px;}
.cd-sim .cd-arrow.up{color:var(--cd-kiwi2);}
.cd-sim .cd-arrow.down{color:var(--cd-red);}
.cd-sim .cd-bar{position:relative;height:18px;border-radius:999px;background:#eef1ec;margin-top:4px;overflow:visible;}
.cd-sim .cd-red{position:absolute;left:0;top:0;bottom:0;width:20%;border-radius:999px 0 0 999px;background:repeating-linear-gradient(45deg,#f8d7d4,#f8d7d4 4px,#fbe9e7 4px,#fbe9e7 8px);}
.cd-sim .cd-fill{position:absolute;left:0;top:0;bottom:0;width:50%;border-radius:999px;transition:width .8s cubic-bezier(.3,.7,.3,1);}
.cd-sim .cd-m-cash .cd-fill{background:linear-gradient(90deg,#e0a63a,var(--cd-cash));}
.cd-sim .cd-m-team .cd-fill{background:linear-gradient(90deg,#a47fd0,var(--cd-team));}
.cd-sim .cd-m-cust .cd-fill{background:linear-gradient(90deg,#ec6f9c,var(--cd-cust));}
.cd-sim .cd-m-fut .cd-fill{background:linear-gradient(90deg,#4fb3a6,var(--cd-fut));}
.cd-sim .cd-m-cash .cd-mval{color:var(--cd-cash);}
.cd-sim .cd-m-team .cd-mval{color:var(--cd-team);}
.cd-sim .cd-m-cust .cd-mval{color:var(--cd-cust);}
.cd-sim .cd-m-fut .cd-mval{color:var(--cd-fut);}
.cd-sim .cd-ghost{display:none;position:absolute;top:-3px;bottom:-3px;width:4px;margin-left:-2px;border-radius:2px;background:var(--cd-ink);opacity:.75;}
.cd-sim .cd-ghost.on{display:block;animation:cdBlink 1s ease-in-out infinite;}
.cd-sim .cd-meter.low .cd-fill{animation:cdPulse 1.2s ease-in-out infinite;}
.cd-sim .cd-meter.zero .cd-bar{animation:cdShake .5s ease-in-out;}
.cd-sim .cd-meter.low .cd-mval{color:var(--cd-red);}
.cd-sim .cd-float{position:absolute;right:0;top:-24px;font-size:.85rem;font-weight:800;opacity:0;pointer-events:none;}
.cd-sim .cd-float.go{animation:cdFloat 1.6s ease-out both;}
.cd-sim .cd-float.up{color:var(--cd-kiwi2);}
.cd-sim .cd-float.down{color:var(--cd-red);}
.cd-sim .cd-mnote{font-size:.8rem;color:var(--cd-soft);margin:6px 0 0;}
/* phone */
.cd-sim .cd-phone{background:#fff;border:3px solid #1d2b22;border-radius:28px;overflow:hidden;box-shadow:0 8px 24px rgba(30,60,30,.18);}
.cd-sim .cd-apphead{display:flex;align-items:center;gap:10px;background:var(--cd-kiwi2);color:#fff;padding:12px 14px;}
.cd-sim .cd-avatar{font-size:1.4rem;background:#fff;border-radius:50%;width:42px;height:42px;display:flex;align-items:center;justify-content:center;flex:none;}
.cd-sim .cd-appwho{flex:1;display:flex;flex-direction:column;min-width:0;}
.cd-sim .cd-appwho b{font-size:1rem;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.cd-sim .cd-appwho small{font-size:.78rem;color:#e6f4e0;}
.cd-sim .cd-battery{font-size:.8rem;}
.cd-sim .cd-thread{height:430px;overflow-y:auto;padding:12px 12px 6px;background:#e9efe2;background-image:radial-gradient(circle at 10px 10px,rgba(47,125,50,.06) 2px,transparent 3px);background-size:22px 22px;display:flex;flex-direction:column;gap:6px;scroll-behavior:smooth;}
.cd-sim .cd-time{align-self:center;font-size:.74rem;font-weight:700;background:#fff;color:var(--cd-soft);border-radius:999px;padding:2px 10px;margin:6px 0 2px;}
.cd-sim .cd-row{display:flex;gap:6px;align-items:flex-end;max-width:88%;}
.cd-sim .cd-row.them{align-self:flex-start;}
.cd-sim .cd-row.me{align-self:flex-end;flex-direction:row-reverse;}
.cd-sim .cd-face{font-size:1.05rem;background:#fff;border-radius:50%;width:30px;height:30px;display:flex;align-items:center;justify-content:center;flex:none;}
.cd-sim .cd-bubble{background:#fff;border-radius:16px 16px 16px 4px;padding:8px 11px;font-size:.92rem;line-height:1.35;box-shadow:0 1px 0 rgba(0,0,0,.08);color:var(--cd-ink);}
.cd-sim .cd-bubble small{display:block;font-size:.72rem;font-weight:800;color:var(--cd-kiwi2);margin-bottom:2px;}
.cd-sim .cd-row.me .cd-bubble{background:var(--cd-me);border-radius:16px 16px 4px 16px;}
.cd-sim .cd-tick{font-size:.7rem;color:#2a6db0;margin-left:6px;font-weight:800;}
.cd-sim .cd-mail{background:#fff;border-left:5px solid #2a6db0;border-radius:10px;padding:8px 11px;font-size:.9rem;line-height:1.35;box-shadow:0 1px 0 rgba(0,0,0,.08);color:var(--cd-ink);}
.cd-sim .cd-mail small{display:block;font-size:.72rem;font-weight:800;color:#1f5689;margin-bottom:2px;}
.cd-sim .cd-sys{align-self:center;font-size:.78rem;background:#fff8e1;color:#5a4300;border-radius:10px;padding:3px 10px;text-align:center;max-width:92%;}
.cd-sim .cd-sys.red{background:#fdecea;color:var(--cd-red);font-weight:700;}
.cd-sim .cd-sys.later{background:#eef4fb;color:#1f4f80;}
.cd-sim .cd-new{animation:cdIn .45s ease-out .9s both;}
.cd-sim .cd-typing{align-self:flex-start;display:flex;gap:4px;background:#fff;border-radius:14px;padding:10px 12px;margin-left:36px;animation:cdGone .01s linear .9s both;}
.cd-sim .cd-typing i{width:7px;height:7px;border-radius:50%;background:#8aa08a;animation:cdDot 1s ease-in-out infinite;}
.cd-sim .cd-typing i:nth-child(2){animation-delay:.15s;}
.cd-sim .cd-typing i:nth-child(3){animation-delay:.3s;}
.cd-sim .cd-dock{border-top:1px solid var(--cd-line);padding:10px 12px 12px;background:#f7faf4;}
.cd-sim .cd-docklabel{font-size:.78rem;font-weight:800;text-transform:uppercase;letter-spacing:.04em;color:var(--cd-kiwi2);margin-bottom:6px;}
.cd-sim .cd-replies{display:flex;flex-direction:column;gap:7px;}
.cd-sim .cd-opt{position:relative;display:flex;align-items:center;gap:10px;border:2px solid var(--cd-line);background:#fff;border-radius:14px;padding:10px 12px;font-size:.93rem;color:var(--cd-ink);cursor:pointer;user-select:none;min-height:52px;margin:0;transition:border-color .12s,background .12s,transform .12s;animation:cdIn .35s ease-out both;}
.cd-sim .cd-opt:nth-child(2){animation-delay:.08s;}
.cd-sim .cd-opt:nth-child(3){animation-delay:.16s;}
.cd-sim .cd-opt input{position:absolute;opacity:0;width:1px;height:1px;margin:0;pointer-events:none;}
.cd-sim .cd-letter{flex:none;width:28px;height:28px;border-radius:50%;background:#eef1ec;color:var(--cd-kiwi2);font-weight:800;display:flex;align-items:center;justify-content:center;font-size:.85rem;}
.cd-sim .cd-opt:hover{border-color:#9cc48a;background:#fbfdf8;}
.cd-sim .cd-opt.sel{border-color:var(--cd-kiwi);background:var(--cd-me);transform:translateX(-3px);}
.cd-sim .cd-opt.sel .cd-letter{background:var(--cd-kiwi2);color:#fff;}
.cd-sim .cd-opt:focus-within{outline:3px solid #1f5fa8;outline-offset:2px;}
.cd-sim .cd-preview{font-size:.84rem;color:var(--cd-soft);margin:8px 0 0;min-height:1.4em;}
.cd-sim .cd-preview b{color:var(--cd-ink);}
.cd-sim .cd-pv{display:inline-block;margin-right:8px;font-weight:800;}
.cd-sim .cd-pv.up{color:var(--cd-kiwi2);}
.cd-sim .cd-pv.down{color:var(--cd-red);}
.cd-sim .cd-pv.flat{color:var(--cd-soft);}
.cd-sim .cd-send{display:block;width:100%;margin-top:10px;background:var(--cd-kiwi2);color:#fff;border:none;border-radius:999px;padding:13px;font-size:1.06rem;font-weight:800;cursor:pointer;min-height:48px;box-shadow:0 3px 0 #17451a;}
.cd-sim .cd-send:hover{background:#1e5a21;}
.cd-sim .cd-send:focus-visible{outline:3px solid #1f5fa8;outline-offset:2px;}
.cd-sim.cd-done .cd-send{background:#6d7d6f;box-shadow:none;}
.cd-sim .cd-summary{display:none;padding:14px 16px;border-top:1px solid var(--cd-line);}
.cd-sim .cd-summary.on{display:block;}
.cd-sim .cd-chartwrap{position:relative;height:230px;}
.cd-sim .cd-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;}
.cd-sim .cd-histwrap{overflow-x:auto;}
.cd-sim .cd-hist{width:100%;border-collapse:collapse;font-size:.84rem;}
.cd-sim .cd-hist th,.cd-sim .cd-hist td{padding:6px 8px;border-bottom:1px solid var(--cd-line);text-align:left;white-space:nowrap;}
/* debrief */
.cd-sim .cd-cm-title{font-size:1.2rem;margin:0 0 6px;}
.cd-sim .cd-cm-score{font-size:1.1rem;font-weight:800;}
.cd-sim .cd-cm-stars{margin-left:8px;color:#8a5a00;letter-spacing:2px;}
.cd-sim .cd-cm-verdict{font-weight:700;color:var(--cd-kiwi2);margin:4px 0 10px;}
.cd-sim .cd-cm-style{background:#f3f8ee;border:2px solid var(--cd-line);border-radius:14px;padding:10px 12px;margin:8px 0;}
.cd-sim .cd-cm-style b{font-size:1.1rem;display:block;}
.cd-sim .cd-cm-style span{font-size:.88rem;color:var(--cd-soft);}
.cd-sim .cd-cm-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-bottom:10px;}
.cd-sim .cd-cm-kpi{background:#f6f8f4;border-radius:10px;padding:8px 4px;text-align:center;}
.cd-sim .cd-cm-kpi b{display:block;font-size:1.15rem;}
.cd-sim .cd-cm-kpi span{font-size:.74rem;color:var(--cd-soft);}
.cd-sim .cd-cm-kpi.red b{color:var(--cd-red);}
.cd-sim .cd-cm h4{margin:12px 0 4px;font-size:.95rem;}
.cd-sim .cd-cm p{font-size:.9rem;margin:4px 0;}
.cd-sim .cd-cm ul,.cd-sim .cd-cm ol{margin:0;padding-left:20px;font-size:.88rem;}
.cd-sim .cd-cm li{margin:3px 0;}
.cd-sim .cd-cm-again{font-size:.88rem;font-weight:700;color:var(--cd-kiwi2);margin-top:10px;}
@keyframes cdIn{from{opacity:0;transform:translateY(8px);}to{opacity:1;transform:none;}}
@keyframes cdGone{to{opacity:0;height:0;padding:0;margin:0;overflow:hidden;}}
@keyframes cdDot{0%,100%{transform:translateY(0);opacity:.5;}50%{transform:translateY(-4px);opacity:1;}}
@keyframes cdFloat{0%{opacity:0;transform:translateY(6px);}15%{opacity:1;}100%{opacity:0;transform:translateY(-16px);}}
@keyframes cdPulse{0%,100%{opacity:1;}50%{opacity:.45;}}
@keyframes cdShake{0%,100%{transform:translateX(0);}25%{transform:translateX(-5px);}75%{transform:translateX(5px);}}
@keyframes cdBlink{0%,100%{opacity:.85;}50%{opacity:.3;}}
@media (max-width:860px){
 .cd-sim{padding:12px;border-radius:0;}
 .cd-sim .cd-grid{grid-template-columns:minmax(0,1fr);grid-template-areas:'meters' 'phone' 'extra';}
 .cd-sim .cd-meters{position:sticky;top:0;z-index:5;padding:8px 10px;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;}
 .cd-sim .cd-meters h3,.cd-sim .cd-mnote{display:none;}
 .cd-sim .cd-meter{margin:0;}
 .cd-sim .cd-mhead{font-size:.74rem;flex-wrap:wrap;gap:2px;}
 .cd-sim .cd-mname{flex:1 1 100%;order:3;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
 .cd-sim .cd-mval{font-size:1rem;min-width:0;}
 .cd-sim .cd-bar{height:12px;}
 .cd-sim .cd-phone{max-width:none;border-radius:20px;}
 .cd-sim .cd-thread{height:52vh;min-height:320px;}
}
@media (max-width:420px){
 .cd-sim .cd-title h1{font-size:1.25rem;}
 .cd-sim .cd-logo{font-size:28px;padding:6px;}
 .cd-sim .cd-chip{padding:5px 9px;font-size:.8rem;}
 .cd-sim .cd-row{max-width:94%;}
 .cd-sim .cd-cm-kpis{grid-template-columns:repeat(2,1fr);}
}
@media (prefers-reduced-motion:reduce){
 .cd-sim *,.cd-sim *::before,.cd-sim *::after{animation:none !important;transition:none !important;}
 .cd-sim .cd-typing{display:none;}
 .cd-sim .cd-thread{scroll-behavior:auto;}
}

js:
/* EQIL guard 1.3 (2026-10-08). Shared block, identical in every sim except SEED and MODE.
   1. Choice decisions start with no option selected and a seeded option order
      (MODE blank: empty selection, original order, for sims that address options by index).
   2. Render timers set while scoring a round wait until the period has advanced.
   3. getHint reads the round that was just scored.
   4. Where the runtime has no eventBus (Open player), a minimal one emits the platform events.
   5. Summary labels and insights returned as translation keys are translated for the platform default debrief.
   6. The framework t() is bound to its instance, so sims that copy it into a local variable keep working.
   7. (1.1) Checkboxes the view ticks by default start unticked until the player ticks them. A restored or
      resumed game keeps its ticks, disabled boxes are left alone, and a tick the player made is never cleared.
   8. (1.2) Text the sim wrote from its own translation table follows the language: after a switch, and whenever
      the sim writes text, a string from another language's table becomes the same key's string in the current one.
   9. (1.2) Randomness drawn while initialising or scoring comes from a generator kept in domainState, so undoing
      a round and submitting it again replays it exactly instead of re-rolling it.
  10. (1.2) Once the run is complete the submit button is disabled; an undo that reopens the run enables it again.
  11. (1.3) A choice keeps its order only when its texts read as a scale (a leading number, %, currency, or two level
      words). Numeric option values alone no longer count: many decisions with named options use 0, 1, 2 as values.
  12. (1.3) The seeded order also depends on the round, so options rebuilt each round are not in the same order
      every round. The same round (a redraw, a language switch, an undo, a resumed game) keeps its order.
   Reviews: Express/testing/eqil_reports/2026-09/EQIL_Portfolio_Finding_open-catalog-review_2026-09-28.md,
   2026-10/EQIL_Portfolio_Finding_model-sweep_2026-10-06.md (EQIL v1.2.0 §15, gates G-F and G-H) */
var __eqilGuard = (function () {
    var SEED = "10008";
    var MODE = "";   // blank: the sim addresses options by position, so no inserted placeholder and no shuffle; empty: placeholder and seeded shuffle
    var TXT = {
        en: ["Choose an option", "Choose an option in every decision before continuing."],
        es: ["Elige una opción", "Elige una opción en cada decisión antes de continuar."],
        ca: ["Tria una opció", "Tria una opció a cada decisió abans de continuar."],
        pt: ["Escolha uma opção", "Escolha uma opção em cada decisão antes de continuar."],
        fr: ["Choisissez une option", "Choisissez une option pour chaque décision avant de continuer."]
    };
    var LEVEL = ["none", "low", "medium", "moderate", "high", "very ", "minimal", "maximum", "conservative", "aggressive",
        "ningun", "bajo", "baja", "medio", "media", "moderad", "alto", "alta", "muy ", "mínim", "máxim", "conservador", "agresiv"];
    var later = window.setTimeout.bind(window);
    var submitted = null;
    var lastRound = null;
    var queued = false;
    var styled = false;
    var groups = {};
    var restoring = false;
    var resumed = false;

    var bus = null;
    function sim() { return window.mySimulation || null; }
    function miniBus() {
        var h = {};
        return {
            on: function (n, f) { (h[n] = h[n] || []).push(f); },
            off: function (n, f) { var a = h[n] || [], k = a.indexOf(f); if (k >= 0) { a.splice(k, 1); } },
            emit: function (n, d) { var a = (h[n] || []).slice(); for (var i = 0; i < a.length; i++) { try { a[i](d); } catch (e) {} } }
        };
    }
    function polyfill(f) {
        if (!f || f.eventBus) { return; }
        bus = miniBus();
        f.eventBus = bus;
        if (typeof f.undo === "function") {
            var u = f.undo;
            f.undo = function () { var r = u.apply(this, arguments); bus.emit("period:undone", this.state); return r; };
        }
        if (typeof f.setLang === "function") {
            var sl = f.setLang;
            f.setLang = function (l) {
                var r = sl.apply(this, arguments);
                bus.emit("language:changed", { lang: l });
                try { document.dispatchEvent(new CustomEvent("express:langchanged", { detail: { lang: l } })); } catch (e) {}
                return r;
            };
        }
    }
    function announce(state, res) {
        if (!bus || !state) { return; }
        var p0 = state.currentPeriod, t0 = Date.now();
        (function check() {
            if (String(state.currentPeriod) !== String(p0) || Date.now() - t0 > 4000) { bus.emit("period:submitted", { results: res, period: p0 }); }
            else { later(check, 40); }
        })();
    }
    function lang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        l = String(l).toLowerCase().slice(0, 2);
        return TXT[l] ? l : "en";
    }
    function roundKey() { var f = sim(); return f && f.state ? String(f.state.currentPeriod) : ""; }
    function hash(s) {
        var h = 2166136261;
        for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
        return h >>> 0;
    }
    function rand(seed) {
        var a = seed;
        return function () {
            a = (a + 0x6D2B79F5) | 0;
            var t = Math.imul(a ^ (a >>> 15), 1 | a);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }
    function permute(items, key) {
        var r = rand(hash(key)), a = items.slice();
        for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(r() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; }
        return a;
    }
    function gameKey(name, values) {
        // 1.3: the round is part of the key, so a select rebuilt every round with the same id and values gets a new
        // order each round (1422 kept one order for all 9 rounds, so always picking the second option scored 88)
        var f = sim(), g = f && f.state && f.state.gameId;
        return SEED + "|" + (g || "") + "|" + roundKey() + "|" + name + "|" + values.join(",");
    }
    function shown(el) {
        for (var n = el; n && n.nodeType === 1; n = n.parentElement) {
            if (n.hidden || n.id === "usfp-overlay") { return false; }
            var cs = window.getComputedStyle ? window.getComputedStyle(n) : null;
            if (cs && (cs.display === "none" || cs.visibility === "hidden")) { return false; }
        }
        return true;
    }
    function skipped(el) {
        if (el.getAttribute("data-eqil-skip") !== null) { return true; }
        return !!(el.closest && el.closest("#usfp-overlay"));
    }
