      G.hours = hours;
      G.picks = hours.map(function(x){ return x.pick; });
      G.meterHistory = hours.map(function(x){ return {at: x.at, cash: x.after.cash, team: x.after.team, cust: x.after.cust, fut: x.after.fut}; });
      var score = this._composite(G);
      G.performance = { overallScore: score, tier: tierOf(score) };
      G.performanceTier = tierOf(score);
      return hours[hours.length - 1];
    }

    /* one formula for the grade, used by every hour and by the final summary */
    _composite(ds){ return MODEL.scoreOf(hoursOf(ds)); }

    _syncControlsFromDecisions(d){
      if(!d) return;
      var sim = window.mySimulation;
      var G = (sim && sim.state && sim.state.domainState) || {};
      if(d.reply && d.scen && d.scen === currentScen(G)){
        var r = el('cdR_' + d.reply); if(r) r.checked = true;
      }
      syncChips();
    }

    setupUI(uiManager){
      uiManager.bind('currentMonth', 'currentPeriod');
      uiManager.bind('maxPeriods', 'maxPeriods');
      wireControls();
      var self = this;
      var sim = window.mySimulation;
      var resync = function(){
        try { if(sim && sim.state) self._syncControlsFromDecisions(sim.state.decisions); } catch(e) { syncChips(); }
      };
      var repaint = function(){
        try { view.threadSig = ''; view.replySig = ''; refresh(); resync(); } catch(e) { syncChips(); }
      };
      document.addEventListener('express:langchanged', repaint);
      try {
        if(sim && sim.eventBus){
          sim.eventBus.on('language:changed', repaint);
          sim.eventBus.on('period:undone', function(){
            repaint();
            /* the undo rebuilds the reply cards: let the shared guard register them now, before the
               player touches them, so the same reply resubmitted replays the hour exactly */
            try { if (typeof __eqilGuard !== 'undefined' && __eqilGuard && typeof __eqilGuard.pass === 'function') { __eqilGuard.pass(); } } catch (e) {}
            try { syncChips(); refresh(); } catch (e) {}
          });
          sim.eventBus.on('state:loaded', function(){ view.seen = -1; repaint(); });
        }
      } catch(e) { syncChips(); }
      setTimeout(repaint, 0);
    }

