        type: 'line',
        data: { labels: [], datasets: [ds('cash', '#b06d00'), ds('team', '#6b3fa0'), ds('cust', '#c2185b'), ds('fut', '#00796b')] },
        options: { responsive: true, maintainAspectRatio: false,
          plugins: { legend: {display: true, labels: {boxWidth: 12}}, title: {display: false} },
          scales: { y: {min: 0, max: 100, ticks: {precision: 0}} } }
      }};
