    getChartData(state){
      var G = state.domainState || {};
      var meterHistory = G.meterHistory || [];
      refresh();
      var series = function(k){ return [MODEL.START].concat(meterHistory.map(function(x){ return x[k]; })); };
      return { cdChart: {
        labels: [t('start_label')].concat(meterHistory.map(function(x){ return x.at; })),
