    getHistoryTableConfig(){
      var num = function(v){ return String(parseInt(v, 10) || 0); };
      return [
        {key: 'results.at',   label: 'Time',      i18nKey: 'col_at',     formatter: function(v){ return String(v || ''); }},
        {key: 'results.who',  label: 'From',      i18nKey: 'col_who',    formatter: function(v){ return v ? t('who_' + v) : ''; }},
        {key: 'results.cash', label: 'Cash',      i18nKey: 'm_cash',     formatter: num},
        {key: 'results.team', label: 'Team',      i18nKey: 'm_team',     formatter: num},
        {key: 'results.cust', label: 'Customers', i18nKey: 'm_cust',     formatter: num},
        {key: 'results.fut',  label: 'Future',    i18nKey: 'm_fut',      formatter: num}
      ];
