    /* everything the debrief says is read from the hours of this run */
    getPerformanceSummary(history){
      var sim = window.mySimulation;
      var G = (sim && sim.state && sim.state.domainState) || {};
      var hours = hoursOf(G);
      if(!hours.length) return {};
      var hist = history || [];
      var score = this._composite(G), tier = tierOf(score);
      var f = MODEL.metersOf(hours);
      var hard = hours[0], hardV = 1e9;
      hours.forEach(function(x){ var lo = Math.min.apply(null, x.d); if(lo < hardV){ hardV = lo; hard = x; } });
      var pickedAt = function(sid, id){ return hours.some(function(x){ return x.scen === sid && x.pick === id; }); };
      return {
        composite: score, overallScore: score, totalScore: score, score: score,
        performance: tier, performanceKey: tier, performanceLabel: t('grade_' + tier), stars: starsOf(score),
        totalPeriods: hours.length, historyRows: hist.length, finished: hours.length >= N,
        style: MODEL.styleOf(hours), meters: f,
        hardAt: hard.at, hardScen: hard.scen, hardPick: hard.pick, hardD: hard.d.slice(),
        zips: pickedAt('zips', 'ship'), back: pickedAt('zips', 'back'), duna: pickedAt('duna', 'sign'), lie: pickedAt('press', 'lie'),
        tired: hours.filter(function(x){ return x.tired; }).length,
        zero: hours.reduce(function(s, x){ return s + x.zero.length; }, 0),
        red: MODEL.METERS.filter(function(k){ return f[k] < MODEL.RED_BELOW; }),
        sales: hours.reduce(function(s, x){ return s + x.sales; }, 0)
      };
    }

    formatCompletionMessage(summary){
      var s = summary || {};
      if(s.overallScore == null || !s.meters) return '<div class="cd-cm"><p>' + esc(t('done_title')) + '</p></div>';
      var kpi = function(k){ var v = s.meters[k]; return '<div class="cd-cm-kpi' + (v < MODEL.RED_BELOW ? ' red' : '') + '"><b>' + MEMO[k] + ' ' + esc(v) + '</b><span>' + esc(meterName(k)) + '</span></div>'; };
      var part = function(sign){
        return MODEL.METERS.map(function(k, i){ var d = s.hardD[i]; return (sign > 0 ? d > 0 : d < 0) ? meterName(k) + ' ' + signed(d) : null; })
          .filter(function(x){ return x; }).join(', ');
      };
      var who = MODEL.SCEN[s.hardScen] ? t('who_' + MODEL.SCEN[s.hardScen].who) : '';
      var hard = t('cm_hard', {at: s.hardAt, who: who, reply: t('sc_' + s.hardScen + '_' + s.hardPick), gain: part(1) || '0', loss: part(-1) || '0'});
      var ins = [];
      if(s.zips) ins.push(t('ins_zips'));
      if(s.back) ins.push(t('ins_back'));
      if(s.duna) ins.push(t('ins_duna'));
      if(s.lie) ins.push(t('ins_lie'));
      if(s.tired) ins.push(t('ins_tired', {n: s.tired}));
      if(s.zero) ins.push(t('ins_zero', {n: s.zero}));
      (s.red || []).forEach(function(k){ ins.push(t('ins_red', {name: meterName(k)})); });
      if(s.sales > 0) ins.push(t('ins_sales', {n: signed(s.sales)}));
      var learn = ['cm_learn_1', 'cm_learn_2', 'cm_learn_3', 'cm_learn_4', 'cm_learn_5'].map(function(k){ return '<li>' + esc(t(k)) + '</li>'; }).join('');
      return '<div class="cd-cm">' +
        '<h3 class="cd-cm-title">' + esc(t('done_title')) + '</h3>' +
        '<div class="cd-cm-score">' + esc(t('cm_score', {score: s.overallScore})) + '<span class="cd-cm-stars" aria-hidden="true">' + s.stars + '</span></div>' +
        '<p class="cd-cm-verdict">' + esc(s.performanceLabel) + '</p>' +
        '<div class="cd-cm-style"><small>' + esc(t('cm_style_h')) + '</small><b>' + esc(t('style_' + s.style)) + '</b><span>' + esc(t('style_' + s.style + '_text')) + '</span></div>' +
        '<h4>' + esc(t('cm_meters_h')) + '</h4><div class="cd-cm-kpis">' + MODEL.METERS.map(kpi).join('') + '</div>' +
        '<h4>' + esc(t('cm_hard_h')) + '</h4><p>' + esc(hard) + '</p>' +
        (ins.length ? '<h4>' + esc(t('cm_ins_h')) + '</h4><ul>' + ins.slice(0, 6).map(function(x){ return '<li>' + esc(x) + '</li>'; }).join('') + '</ul>' : '') +
        '<h4>' + esc(t('cm_learn_h')) + '</h4><ul>' + learn + '</ul>' +
        '<h4>' + esc(t('cm_q_h')) + '</h4><ol>' + ['cm_q1', 'cm_q2', 'cm_q3'].map(function(k){ return '<li>' + esc(t(k)) + '</li>'; }).join('') + '</ol>' +
        '<p class="cd-cm-again">' + esc(t('cm_again')) + '</p>' +
        '</div>';
    }

